import { useState, useRef } from "react";
import StudentLayout from "./StudentLayout";
import { Outlet } from "react-router-dom"; // تأكد من وجود Outlet في الـ Layout

const ALL_SKILLS = ["React", "Node.js", "Django", "Python", "Java", "Flutter", "SQL", "Git", "Docker", "Figma"];
const WILAYAS = ["Alger", "Constantine", "Oran", "Sétif", "Annaba", "Béjaïa"];
const LEVELS = ["L1", "L2", "L3", "M1", "M2"];

export default function StudentProfile() {
  // 1. الحالة الأساسية (Dynamic State)
  const [profile, setProfile] = useState({
    firstName: "Amira",
    lastName: "Benali",
    email: "amira.benali@ifa.edu.dz",
    phone: "+213 555 123 456",
    university: "IFA — Constantine 2",
    department: "Informatique",
    level: "L3",
    wilaya: "Constantine",
    bio: "Passionate CS student looking for an internship...",
    skills: ["React", "Node.js"],
    github: "https://github.com/amira-benali",
    digitalCV: null,
    education: [
      { id: 1, degree: "Licence TI", school: "IFA", year: "2023-2026" }
    ]
  });

  const [editing, setEditing] = useState(false);
  const [tab, setTab] = useState("info");

  // 2. دوال التحديث الديناميكي (Handlers)
  const handleChange = (e) => {
    const { name, value } = e.target;
    setProfile(prev => ({ ...prev, [name]: value }));
  };

  const toggleSkill = (skill) => {
    setProfile(prev => ({
      ...prev,
      skills: prev.skills.includes(skill) 
        ? prev.skills.filter(s => s !== skill) 
        : [...prev.skills, skill]
    }));
  };

  const addEducation = () => {
    const newEdu = { id: Date.now(), degree: "", school: "", year: "" };
    setProfile(prev => ({ ...prev, education: [...prev.education, newEdu] }));
  };

  const updateEducation = (id, field, value) => {
    setProfile(prev => ({
      ...prev,
      education: prev.education.map(edu => edu.id === id ? { ...edu, [field]: value } : edu)
    }));
  };

  // 3. مكون الحقل الديناميكي (Reusable Component)
  const DynamicField = ({ label, name, value, type = "text", options = null }) => (
    <div className="mb-4">
      <label className="block text-xs font-bold text-slate-500 uppercase mb-1.5">{label}</label>
      {editing ? (
        options ? (
          <select name={name} value={value} onChange={handleChange} className="w-full p-2.5 bg-white border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none">
            {options.map(opt => <option key={opt} value={opt}>{opt}</option>)}
          </select>
        ) : (
          <input name={name} type={type} value={value} onChange={handleChange} className="w-full p-2.5 bg-white border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" />
        )
      ) : (
        <div className="p-2.5 bg-slate-50 rounded-xl text-slate-700 font-medium border border-transparent">
          {value || <span className="text-slate-400 italic">Not set</span>}
        </div>
      )}
    </div>
  );

  return (
    <StudentLayout active="profile">
      <div className="max-w-4xl mx-auto p-6">
        
        {/* Header Section */}
        <div className="flex justify-between items-center mb-8 bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-4">
            <div className="w-16 h-16 bg-gradient-to-tr from-blue-600 to-blue-400 rounded-2xl flex items-center justify-center text-white text-2xl font-bold">
              {profile.firstName[0]}{profile.lastName[0]}
            </div>
            <div>
              <h1 className="text-2xl font-extrabold text-slate-900">{profile.firstName} {profile.lastName}</h1>
              <p className="text-slate-500 text-sm">{profile.level} {profile.department} @ {profile.university}</p>
            </div>
          </div>
          <button 
            onClick={() => setEditing(!editing)}
            className={`px-6 py-2.5 rounded-xl font-bold text-sm transition-all ${editing ? "bg-green-500 text-white shadow-lg shadow-green-200" : "bg-slate-900 text-white"}`}
          >
            {editing ? "✓ Save Profile" : "✎ Edit Profile"}
          </button>
        </div>

        {/* Tabs Selection */}
        <div className="flex gap-2 mb-6">
          {["info", "skills", "education", "preview"].map(t => (
            <button 
              key={t} onClick={() => setTab(t)}
              className={`px-4 py-2 rounded-lg text-sm font-bold capitalize ${tab === t ? "bg-blue-600 text-white" : "bg-white text-slate-500 border border-slate-100"}`}
            >
              {t}
            </button>
          ))}
        </div>

        {/* Tab Content: Info */}
        {tab === "info" && (
          <div className="grid md:grid-cols-2 gap-6 bg-white p-6 rounded-2xl border border-slate-100 shadow-sm animate-in fade-in duration-500">
            <DynamicField label="First Name" name="firstName" value={profile.firstName} />
            <DynamicField label="Last Name" name="lastName" value={profile.lastName} />
            <DynamicField label="University (Class Diagram)" name="university" value={profile.university} />
            <DynamicField label="Wilaya (Class Diagram)" name="wilaya" value={profile.wilaya} options={WILAYAS} />
            <div className="md:col-span-2">
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1.5">Bio / Summary</label>
              {editing ? (
                <textarea name="bio" value={profile.bio} onChange={handleChange} rows="3" className="w-full p-2.5 border border-slate-200 rounded-xl outline-none" />
              ) : (
                <p className="p-3 bg-slate-50 rounded-xl text-slate-600 leading-relaxed">{profile.bio}</p>
              )}
            </div>
          </div>
        )}

        {/* Tab Content: Skills */}
        {tab === "skills" && (
          <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
            <h3 className="font-bold text-slate-800 mb-4">Technical Skills (Matching Engine)</h3>
            <div className="flex flex-wrap gap-2">
              {ALL_SKILLS.map(skill => (
                <button
                  key={skill}
                  disabled={!editing}
                  onClick={() => toggleSkill(skill)}
                  className={`px-4 py-2 rounded-full text-xs font-bold border transition-all ${
                    profile.skills.includes(skill) 
                    ? "bg-blue-600 border-blue-600 text-white" 
                    : "bg-white border-slate-200 text-slate-500"
                  }`}
                >
                  {skill} {profile.skills.includes(skill) && "✕"}
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Tab Content: Education (Fully Dynamic List) */}
        {tab === "education" && (
          <div className="space-y-4">
            {profile.education.map((edu) => (
              <div key={edu.id} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm relative">
                <div className="grid md:grid-cols-3 gap-4">
                  <div>
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Degree</label>
                    <input 
                      disabled={!editing} 
                      value={edu.degree} 
                      onChange={(e) => updateEducation(edu.id, "degree", e.target.value)}
                      className="w-full font-bold text-slate-800 bg-transparent outline-none disabled:opacity-100"
                      placeholder="e.g. Licence TI"
                    />
                  </div>
                  <div>
                    <label className="text-[10px] font-bold text-slate-400 uppercase">School</label>
                    <input 
                      disabled={!editing} 
                      value={edu.school} 
                      onChange={(e) => updateEducation(edu.id, "school", e.target.value)}
                      className="w-full text-slate-600 bg-transparent outline-none"
                      placeholder="University Name"
                    />
                  </div>
                  <div>
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Year</label>
                    <input 
                      disabled={!editing} 
                      value={edu.year} 
                      onChange={(e) => updateEducation(edu.id, "year", e.target.value)}
                      className="w-full text-slate-400 bg-transparent outline-none"
                      placeholder="2024 - Present"
                    />
                  </div>
                </div>
              </div>
            ))}
            {editing && (
              <button onClick={addEducation} className="w-full py-3 border-2 border-dashed border-slate-200 rounded-2xl text-slate-400 font-bold hover:border-blue-400 hover:text-blue-500 transition-all">
                + Add Education Entry
              </button>
            )}
          </div>
        )}

      </div>
    </StudentLayout>
  );
}
